import * as THREE from 'three';
import {createFantasy} from './fantasy.js';
export function createMaterials(){
const textureCanvas=document.createElement('canvas');textureCanvas.width=textureCanvas.height=256;const ctx=textureCanvas.getContext('2d');ctx.fillStyle='#545b59';ctx.fillRect(0,0,256,256);for(let row=0;row<8;row++)for(let col=-1;col<5;col++){const x=col*64+(row%2)*32,y=row*32;ctx.fillStyle=['#818984','#969b8b','#777f7d'][(row*3+col+6)%3];ctx.fillRect(x+2,y+2,60,28);}const tex=new THREE.CanvasTexture(textureCanvas);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.colorSpace=THREE.SRGBColorSpace;tex.repeat.set(1,1);
const M={stone:new THREE.MeshStandardMaterial({map:tex,roughness:1}),plaster:new THREE.MeshStandardMaterial({color:0xe2d5b7,roughness:1}),wood:new THREE.MeshStandardMaterial({color:0x463126,roughness:1}),floor:new THREE.MeshStandardMaterial({color:0x94744d,roughness:1,side:THREE.DoubleSide}),glass:new THREE.MeshStandardMaterial({color:0x244653,roughness:.4}),door:new THREE.MeshStandardMaterial({color:0x50382b}),ground:new THREE.MeshStandardMaterial({color:0x899875,roughness:1}),road:new THREE.MeshStandardMaterial({color:0xb5aa8c}),ghost:new THREE.MeshStandardMaterial({color:0x849396,transparent:true,opacity:.3,depthWrite:false})};
return M;}
export function createShellBuilder({materials:M,invalidate=()=>{},detail=.45,coarse=false}){let plan;
function box(group,x,y,z,w,h,d,material,rot=0){const g=new THREE.BoxGeometry(w,h,d),m=new THREE.Mesh(g,material);m.position.set(x,y+h/2,z);m.rotation.y=rot;m.castShadow=m.receiveShadow=true;group.add(m);return m;}
function strip(group,a,b,y,h,material,thickness=.18){const dx=b[0]-a[0],dz=b[1]-a[1];return box(group,(a[0]+b[0])/2,y,(a[1]+b[1])/2,Math.hypot(dx,dz),h,thickness,material,-Math.atan2(dz,dx));}
function floorMesh(group,loop,y,material=M.floor){const v=loop.map(p=>new THREE.Vector2(...p)),faces=THREE.ShapeUtils.triangulateShape(v,[]),g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(loop.flatMap(p=>[p[0],y,p[1]]),3));g.setIndex(faces.flat());g.computeVertexNormals();const mesh=new THREE.Mesh(g,material);mesh.receiveShadow=true;group.add(mesh);}
function clear(group){group.traverse(o=>o.geometry?.dispose());group.clear();}
function wall(group,e,f){const a=e.a,b=e.b,dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz),at=t=>[a[0]+dx*t,a[1]+dz*t],material=f===0?M.stone:M.plaster,y=f*3;
 const panel=(a,b,yy,hh)=>{const low=Math.max(yy,y+(f?.16:0)),high=Math.min(yy+hh,y+(f?2.85:3.005));if(high-low>1e-5)strip(group,a,b,low,high-low,material);};
 const door=f===0?plan.door:plan.exteriorDoors?.find(d=>d.level===f&&Math.abs((d.x-a[0])*dz-(d.z-a[1])*dx)<1e-6&&((d.x-a[0])*dx+(d.z-a[1])*dz)>0&&((d.x-a[0])*dx+(d.z-a[1])*dz)<len*len),custom=door?.edge,doorAlong=custom?((door.x-a[0])*dx+(door.z-a[1])*dz)/(len*len):0;
 const entrance=!!door&&(custom?doorAlong>.01&&doorAlong<.99&&Math.abs((door.x-a[0])*dz-(door.z-a[1])*dx)<1e-6:Math.abs(a[1]-plan.front)<1e-5&&Math.abs(b[1]-plan.front)<1e-5&&plan.door.x>Math.min(a[0],b[0])&&plan.door.x<Math.max(a[0],b[0]));
 if(entrance){const mid=custom?doorAlong:(plan.door.x-a[0])/dx,half=door.width/(2*len),lo=Math.max(0,mid-half),hi=Math.min(1,mid+half);if(lo>0)panel(a,at(lo),y,3);if(hi<1)panel(at(hi),b,y,3);panel(at(lo),at(hi),y+2.25,.75);strip(group,at(lo),at(hi),y,2.2,M.door,.1);
 }else if(len>1.2){const n=Math.max(1,Math.floor(len/2));for(let i=0;i<n;i++){const lo=i/n,hi=(i+1)/n,mid=(lo+hi)/2,half=Math.min(.5,(len/n-.35)/2)/len;panel(at(lo),at(mid-half),y,3);panel(at(mid+half),at(hi),y,3);panel(at(mid-half),at(mid+half),y,.9);panel(at(mid-half),at(mid+half),y+2.15,.85);strip(group,at(mid-half),at(mid+half),y+.92,1.2,M.glass,.045);strip(group,at(mid-half),at(mid+half),y+.84,.09,M.wood,.24);strip(group,at(mid-half),at(mid+half),y+2.15,.09,M.wood,.24);const midp=at(mid);box(group,midp[0],y+.9,midp[1],.055,1.3,.24,M.wood,-Math.atan2(dz,dx));}}
 else panel(a,b,y,3);
}
function coarseWall(group,e,f){if(f===0||plan.exteriorDoors?.some(d=>d.level===f&&d.edge===e)){wall(group,e,f);return;}const a=e.a,b=e.b,dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz),rot=-Math.atan2(dz,dx),y=f*3,at=(t,offset)=>[a[0]+dx*t+dz/len*offset,a[1]+dz*t-dx/len*offset],plane=(point,yy,w,h,material)=>{const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),material);m.position.set(point[0],yy,point[1]);m.rotation.y=rot+Math.PI;group.add(m);};strip(group,a,b,y,3,f?M.plaster:M.stone);if(f>0)for(const t of [.07/len,1-.07/len])plane(at(t,.104),y+1.505,.14,2.69,M.wood);if(len>1.2){const n=Math.max(1,Math.floor(len/2));for(let i=0;i<n;i++){const t=(i+.5)/n,w=Math.min(1,len/n-.3);plane(at(t,.102),y+1.525,w+.16,1.41,M.wood);plane(at(t,.107),y+1.525,w,1.25,M.glass);}}}
function geometry(group,positions,material,name){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.computeVertexNormals();const mesh=new THREE.Mesh(g,material);mesh.name=name;mesh.castShadow=mesh.receiveShadow=true;group.add(mesh);return mesh;}
function timber(group,loop,y){for(const [yy,h] of [[y,.16],[y+2.85,.15]])geometry(group,ShapeStudyTrim.ring(loop,yy,h),M.wood,'continuous timber ring');for(const p of coarse?[]:ShapeStudyTrim.posts(loop)){const mesh=box(group,p[0],y+.16,p[1],.22,2.69,.22,M.wood);mesh.name='unique corner post';}}

const fantasy=createFantasy({materials:M,box,strip,geometry,invalidate,detail,coarse});
function build(input,{count=input.storeys,storybook=true,dressing=true,roofs=true}={}){plan=input;const root=new THREE.Group();
for(const f of plan.floors.slice(0,count)){for(const loop of f.loops){floorMesh(root,loop,f.y+.015);if(f.level===0&&count===1)geometry(root,ShapeStudyTrim.ring(loop,3.005,.1),M.stone,'stone coping');}for(const edge of f.edges)(coarse?coarseWall:wall)(root,edge,f.level);if(f.level>0)for(const loop of f.loops)timber(root,loop,f.y);}
 if(plan.accent&&count===plan.storeys){floorMesh(root,plan.accent.poly,plan.storeys*3+.015);timber(root,plan.accent.poly,plan.storeys*3);for(const e of PlotShapeStudy.boundary([plan.accent.poly]))(coarse?coarseWall:wall)(root,e,plan.storeys);}
 // Every cantilever bracket starts on the floor below, rather than assuming an unchanged facade.
 for(let level=1;!coarse&&level<count;level++){const below=plan.floors[level-1],floor=plan.floors[level];for(const p of ShapeStudyTrim.posts(floor.loops[0])){if(below.parts.some(part=>PlotShapeStudy.inside(p,part.poly)))continue;let nearest=null,best=Infinity;for(const e of below.edges){const dx=e.b[0]-e.a[0],dz=e.b[1]-e.a[1],t=THREE.MathUtils.clamp(((p[0]-e.a[0])*dx+(p[1]-e.a[1])*dz)/(dx*dx+dz*dz),0,1),q=[e.a[0]+dx*t,e.a[1]+dz*t],d=Math.hypot(p[0]-q[0],p[1]-q[1]);if(d<best){best=d;nearest=q;}}if(best<.18||best>2.8)continue;const a=new THREE.Vector3(nearest[0],floor.y-.6,nearest[1]),b=new THREE.Vector3(p[0],floor.y+.02,p[1]),curve=new THREE.QuadraticBezierCurve3(a,new THREE.Vector3(a.x*.55+b.x*.45,floor.y-.12,a.z*.55+b.z*.45),b);for(let k=0;k<5;k++){const start=curve.getPoint(k/5),end=curve.getPoint((k+1)/5),delta=end.clone().sub(start),m=new THREE.Mesh(new THREE.BoxGeometry(.14,delta.length()+.005,.14),M.wood);m.name='anchored curved bracket';m.position.copy(start.add(end).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());m.castShadow=true;root.add(m);}}}
 if(storybook&&dressing)fantasy.dressing(root,plan,count);if(roofs&&count===plan.storeys){fantasy.roofs(root,plan,storybook);for(const lower of plan.lowerRoofs||[]){const poly=lower.poly,xs=poly.map(p=>p[0]),zs=poly.map(p=>p[1]),width=Math.max(...xs)-Math.min(...xs),depth=Math.max(...zs)-Math.min(...zs),f={level:lower.storeys-1,y:(lower.storeys-1)*3,parts:[{id:'main',poly}],loops:[poly],edges:PlotShapeStudy.boundary([poly])};fantasy.roofs(root,{...plan,form:'wing',character:'grounded',accent:null,lowerRoofs:[],width,depth,front:Math.min(...zs),back:Math.max(...zs),storeys:lower.storeys,floors:[f],roofType:'hip',roofScaleWidth:Math.min(width,depth),roofClip:lower.clip||ShapeStudyTrim.offset(poly,.3)},false);}}

return root;}return {build};}
